/**
 * A value shown as text, edited in place (`design/components/inline-edit.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/inline-edit.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  afterRender,
  agentMember,
  claimSlot,
  composingKey,
  createCell,
  createDerived,
  elementRef,
  holdFieldEscape,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/inline-edit.module.css'
import Button from './Button'
import Input from './Input'

export interface InlineEditMessages {
  edit: (label: string) => string
  save: string
  cancel: string
}

export interface InlineEditProps {
  /**
   * The id of a description of the field and the edit control, as SettingsRow's.
   */
  'aria-describedby'?: string
  /**
   * The id of a label elsewhere that names the field, as SettingsRow's row label does.
   */
  'aria-labelledby'?: string
  /**
   * Uncontrolled: whether the field is open when the member mounts. It takes no focus then.
   */
  defaultEditing?: boolean
  /**
   * The edit control is disabled. The value stays as it is.
   */
  disabled?: boolean
  /**
   * Controlled: whether the field is open. The app closes it once a save succeeds.
   */
  editing?: boolean
  /**
   * The app's message for a failed save, drawn under the field while it is open.
   */
  error?: string
  /**
   * Names the field ("Project name") and, through `messages.edit`, the edit control.
   */
  label: string
  maxLength?: number
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: InlineEditMessages
  /**
   * The reader saved a changed text, reported as typed. An uncontrolled field closes at once. A
   * controlled one (`editing`) stays open until the app closes it. Not called for an unchanged
   * text.
   */
  onCommit: (value: string) => void
  /**
   * The reader opened the field, cancelled, or saved an unchanged text.
   */
  onEditingChange?: (editing: boolean) => void
  /**
   * A save is in flight: the field is read-only, save is busy and cancel is disabled.
   */
  pending?: boolean
  /**
   * Drawn, muted, in place of an empty value, and the empty field's placeholder.
   */
  placeholder?: string
  /**
   * A blank text cannot be saved: the save control is disabled and Enter does nothing.
   */
  required?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * The saved value, drawn as text. The app owns it, so after a save it passes the new value.
   */
  value: string
  /**
   * Another element beside the member draws the value, as a page's `<h1>` does: the member draws
   * its edit control and its field, and the value describes the edit control without being
   * drawn. A page's `titleEdit` sets it.
   */
  valueHidden?: boolean
}

/** A value shown as text, edited in place. */
export default function InlineEdit(given: InlineEditProps): JSX.Element {
  const props = mergeProps(
    {
      defaultEditing: false,
      pending: false,
      required: false,
      disabled: false,
      size: 'md',
      valueHidden: false,
      messages: (() => ({ edit: (label) => `Edit ${label}`, save: 'Save', cancel: 'Cancel' }))(),
    } as Defaults<
      InlineEditProps,
      'defaultEditing' | 'pending' | 'required' | 'disabled' | 'size' | 'valueHidden' | 'messages'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const root = elementRef<HTMLElement>()
    const mirror = createCell(props.defaultEditing)
    const draft = createCell(props.value)
    const within = createCell(false)
    const current = createDerived(() => props.editing ?? mirror.value)
    const valueId = createDerived(() => `${uid}-value`)
    const errorId = createDerived(() => `${uid}-error`)
    const refused = createDerived(() => props.required && draft.value.trim() === '')
    const invalid = createDerived(
      () => current.value && props.error !== undefined && props.error !== '',
    )
    const fieldDescribedBy = createDerived(
      () =>
        [invalid.value ? errorId.value : undefined, props['aria-describedby']]
          .filter((id) => id !== undefined)
          .join(' ') || undefined,
    )
    const editDescribedBy = createDerived(() =>
      props['aria-describedby'] === undefined
        ? valueId.value
        : `${valueId.value} ${props['aria-describedby']}`,
    )
    const setOpen = createDerived(() => (next: boolean) => {
      mirror.value = next
      props.onEditingChange?.(next)
    })
    const open = createDerived(() => () => {
      draft.value = props.value
      setOpen.value(true)
    })
    const cancel = createDerived(() => () => {
      if (!props.pending) setOpen.value(false)
    })
    const commit = createDerived(() => () => {
      if (props.pending || refused.value) return
      if (draft.value === props.value) {
        setOpen.value(false)
        return
      }
      props.onCommit?.(draft.value)
      if (props.editing === undefined) setOpen.value(false)
    })
    const onKey = createDerived(() => (event: KeyboardEvent) => {
      if (composingKey(event)) return
      if (event.key === 'Escape') {
        event.preventDefault()
        cancel.value()
        return
      }
      if (event.key === 'Enter' && event.target instanceof HTMLInputElement) {
        event.preventDefault()
        commit.value()
      }
    })
    const cancellable = createDerived(() => current.value && !props.pending)
    const leave = createDerived(() => (event: FocusEvent) => {
      const next = event.relatedTarget
      if (next instanceof Node && !(root.value?.contains(next) ?? false)) within.value = false
    })
    const saveText = createDerived(() => (text: string) => {
      if (!current.value) throw new Error('The field is closed: edit opens it.')
      if (props.pending) throw new Error('A save is in flight.')
      if (props.required && text.trim() === '') throw new Error('The field is required.')
      draft.value = text
      if (text === props.value) {
        setOpen.value(false)
        return
      }
      props.onCommit?.(text)
      if (props.editing === undefined) setOpen.value(false)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = cancellable.value && root.value ? holdFieldEscape(root.value) : () => {}
      release1 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => cancellable.value),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    const effect2 = () => {
      void (current.value
        ? ((draft.value = props.value),
          afterRender(() => {
            const input = root.value?.querySelector('input')
            input?.focus()
            input?.select()
          }))
        : within.value && afterRender(() => root.value?.querySelector('button')?.focus()))
    }
    watchEffect(
      createMemo(() => current.value),
      effect2,
      false,
    )
    const effect3 = () => {
      void (
        !props.pending &&
        current.value &&
        within.value &&
        root.value?.querySelector('input')?.focus()
      )
    }
    watchEffect(
      createMemo(() => props.pending),
      effect3,
      false,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = agentMember({
        member: 'InlineEdit',
        element: () => root.value?.querySelector('input') ?? root.value?.querySelector('button'),
        state: () => ({
          value: props.value,
          editing: current.value,
          pending: props.pending,
          error: invalid.value ? (props.error ?? '') : '',
          disabled: props.disabled,
        }),
        actions: {
          edit: () =>
            (() => {
              if (!current.value) open.value()
            })(),
          save: { argument: 'text', run: (value) => saveText.value(value) },
          cancel: () =>
            (() => {
              if (props.pending) throw new Error('A save is in flight.')
              if (current.value) setOpen.value(false)
            })(),
        },
        withholds: () => root.value,
      })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <div
        class={styles.root}
        data-size={props.size}
        data-disabled={props.disabled ? '' : undefined}
        data-editing={current.value ? '' : undefined}
        data-member="inline-edit"
        onfocusin={() => (within.value = true)}
        onfocusout={($event: FocusEvent) => leave.value($event)}
        ref={root.attach}
      >
        {current.value ? (
          <div
            class={styles.panel}
            data-inline-edit-part="panel"
            onkeydown={($event: KeyboardEvent) => onKey.value($event)}
          >
            {/* row */}
            <div class={styles.row}>
              {/* field */}
              <div class={styles.field}>
                <Input
                  size={props.size}
                  value={draft.value}
                  placeholder={props.placeholder}
                  maxLength={props.maxLength}
                  readOnly={props.pending}
                  disabled={props.disabled}
                  invalid={invalid.value}
                  aria-label={props['aria-labelledby'] === undefined ? props.label : undefined}
                  aria-labelledby={props['aria-labelledby']}
                  aria-describedby={fieldDescribedBy.value}
                  aria-required={props.required ? true : undefined}
                  onChange={($event) => (draft.value = $event)}
                />
              </div>
              <Button
                variant="soft"
                tone="accent"
                size={props.size}
                iconOnly={true}
                icon="confirm"
                label={props.messages.save}
                loading={props.pending}
                disabled={props.disabled || refused.value}
                onClick={() => commit.value()}
              />
              <Button
                variant="ghost"
                tone="neutral"
                size={props.size}
                iconOnly={true}
                icon="close"
                label={props.messages.cancel}
                disabled={props.disabled || props.pending}
                onClick={() => cancel.value()}
              />
            </div>
            {/* status */}
            <div aria-live="polite">
              {invalid.value ? (
                <p class={styles.error} id={errorId.value}>
                  {/* glyph */}
                  <span class={styles.glyph}>
                    <Icon name="error" size="sm" />
                  </span>
                  {props.error}
                </p>
              ) : null}
            </div>
          </div>
        ) : (
          <>
            {/* value */}
            <span
              class={styles.value}
              id={valueId.value}
              hidden={props.valueHidden}
              data-placeholder={props.value === '' ? '' : undefined}
            >
              {(props.value === '' ? props.placeholder : props.value) ?? ''}
            </span>
            <Button
              variant="ghost"
              tone="neutral"
              size={props.size}
              iconOnly={true}
              icon="edit"
              label={props.messages.edit(props.label)}
              disabled={props.disabled}
              aria-describedby={editDescribedBy.value}
              onClick={() => open.value()}
            />
          </>
        )}
      </div>
    )
  })
}
